import{z as A,x as o,o as e,c as s,q as i,j as l,D as a,d as B,s as n,S as r}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"不可能三角","description":"","frontmatter":{"title":"不可能三角","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/impossible-trinity.md","filePath":"econ/impossible-trinity.md","lastUpdated":1791413859000}'),p={name:"econ/impossible-trinity.md"};function d(C,E,m,h,_,c){const t=o("Mermaid");return e(),s("div",null,[E[2]||(E[2]=i('<h1 id="不可能三角" tabindex="-1">不可能三角 <a class="header-anchor" href="#不可能三角" aria-label="Permalink to &quot;不可能三角&quot;">​</a></h1><div class="epigraph"><p>独立的货币政策、固定汇率、资本自由流动，三者不能同时成立；选两个，第三个必须放弃。</p><footer>—— 据 Mundell 开放宏观的政策分派；Fleming 固定与浮动下的稳定政策</footer></div><p><a href="/econ/monetary-union">上一课</a>（货币同盟）。已经在完全资本流动下看到：钉住 \\(E\\) 则 \\(M\\) 内生，\\(i\\) 钉住 \\(i^*\\)。本课把这句话收成制度选择，不再重画 IS–LM。三角是政策空间的边界，不是又一条核算恒等。宏观主干的开放课序还有后课；金融中介为什么仍然存在，之后才问——无论三角选哪一边，不可交易的初级债权还在。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三个目标各有理由：独立货币（选自己的 \\(\\pi^*\\) 与泰勒规则）、固定汇率（减少 \\(q\\) 的短波动、或作为名义锚）、资本开放（跨期贸易、配置）。Mundell 的装置表明它们不相容。缺口是把不相容写成清楚的三选二，并接到已经学过的中性、PPP、铸币税：你不能既把 \\(P\\) 的趋势交给外国锚，又用本国 \\(H\\) 去征独立的通胀税，还让资本按 \\(i\\) 自由套利。</p><p>中间制度（有管理浮动、有限管制）是三角内部的折中，不是第四个顶点。卢卡斯批判：宣布「三个都要」而实际会放弃其中一个，预期会对准将被放弃的那个。</p><p><span class="marginnote">三角可以类比「钱多、活少、离家近」最多占两样：招聘广告若宣称三样全占，问题一定藏在角落里。制度承诺同理——宣称同时钉住汇率、开放资本、又独立定利率，市场会去找出那条注定要放弃的边，并且提前对它下注。</span></p><p><span class="marginnote">三角约束的是<strong>同时</strong>的制度。可以随时间改组合：先资本管制再开放，或放弃钉住。那是制度变迁，不是某一年违反了会计。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三个顶点：</p><ul><li>开放资本 + 固定 \\(E\\) → 放弃独立货币（货币局、美元化、硬钉住）。</li><li>开放资本 + 独立货币 → 放弃固定 \\(E\\)（浮动，PPP 在长期吸收 \\(\\pi-\\pi^*\\)）。</li><li>固定 \\(E\\) + 独立货币 → 放弃自由资本（管制，BP 不再把 \\(i\\) 钉死）。</li></ul>',11)),(e(),l(r,null,{default:a(()=>[n(t,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%B8%89%E9%80%89%E4%BA%8C%22%5D%20--%3E%20A%5B%22%E5%BC%80%E6%94%BE%2B%E9%92%89%E4%BD%8F%20%E2%86%92%20%E8%B4%A7%E5%B8%81%E4%B8%8D%E7%8B%AC%E7%AB%8B%22%5D%0A%20%20T%20--%3E%20B%5B%22%E5%BC%80%E6%94%BE%2B%E7%8B%AC%E7%AB%8B%E8%B4%A7%E5%B8%81%20%E2%86%92%20E%20%E6%B5%AE%E5%8A%A8%22%5D%0A%20%20T%20--%3E%20C%5B%22%E9%92%89%E4%BD%8F%2B%E7%8B%AC%E7%AB%8B%E8%B4%A7%E5%B8%81%20%E2%86%92%20%E8%B5%84%E6%9C%AC%E7%AE%A1%E5%88%B6%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=i('<p>泰勒规则在浮动角上对本国 \\(\\pi\\) 操作；在硬钉住角上，本国规则必须复制外国 \\(i^*\\)，否则储备耗尽。时间不一致：宣布钉住却在压力下想用独立 \\(i\\) 来顾国内缺口，是三角上的再优化，结果是挤兑储备或突然浮动。</p><h3 id="与核算、中性的对齐" tabindex="-1">与核算、中性的对齐 <a class="header-anchor" href="#与核算、中性的对齐" aria-label="Permalink to &quot;与核算、中性的对齐&quot;">​</a></h3><p>\\(CA=S-I\\) 在三角每一角都成立。独立货币的长期含义仍是本国 \\(\\pi\\) 由本国名义锚定；钉住则进口外国 \\(\\pi\\)。铸币税在钉住角上受限于为维持 \\(E\\) 而必须提供的外汇——不能任意抽通胀税。下限在开放角上可通过 \\(E\\) 部分减压，但外国也在下限时渠道变窄。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无抛补套利把 \\(i\\) 接到 \\(i^*+\\mathbb{E}\\Delta e\\)。若政策同时保证 \\(\\Delta e=0\\)、资本无摩擦、又要把 \\(i\\) 调离 \\(i^*\\)，套利资金无限，储备或汇率必破。管制提高套利成本，等于让 \\(i\\) 暂时独立，代价是跨期贸易与规避。浮动让 \\(\\mathbb{E}\\Delta e\\) 去吸收 \\(i\\) 差，PPP 与数量论在长期把 \\(E\\) 拉到与 \\(P/P^*\\) 一致。</p><p><span class="marginnote">数字实例：本国利率 5%、外国利率 2%，汇率宣布固定且资本随便进出——全世界的借款人都会来借 2 厘的外国钱、存进来吃 5 厘，利差 3 个点乘以无限的套利资金，就是央行账本上填不满的窟窿。三全其美不是难，是算术上不成立。</span></p>',6)),(e(),l(r,null,{default:a(()=>[n(t,{id:"mermaid-64",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRY%5B%22%E5%90%8C%E6%97%B6%E6%83%B3%E8%A6%81%3A%20%E5%9B%BA%E5%AE%9AE%20%2B%20%E5%BC%80%E6%94%BE%E8%B5%84%E6%9C%AC%20%2B%20i%20%E5%81%8F%E7%A6%BB%20i*%22%5D%20--%3E%20ARB%5B%22%E5%A5%97%E5%88%A9%E8%80%85%E7%9C%8B%E5%88%B0%E6%97%A0%E9%A3%8E%E9%99%A9%E5%88%A9%E5%B7%AE%22%5D%0A%20%20ARB%20--%3E%20FLOW%5B%22%E8%B5%84%E6%9C%AC%E6%97%A0%E9%99%90%E6%B5%81%E5%85%A5%E6%88%96%E6%B5%81%E5%87%BA%22%5D%0A%20%20FLOW%20--%3E%20CHOICE%7B%22%E5%A4%AE%E8%A1%8C%E5%8F%AA%E8%83%BD%E4%B8%89%E9%80%89%E4%B8%80%22%7D%0A%20%20CHOICE%20--%3E%7C%22%E4%B9%B0%E5%8D%96%E5%A4%96%E6%B1%87%E4%BF%9D%20E%22%7C%20RES%5B%22%E5%82%A8%E5%A4%87%E8%80%97%E5%B0%BD%E6%88%96%E6%97%A0%E9%99%90%E8%86%A8%E8%83%80%22%5D%0A%20%20CHOICE%20--%3E%7C%22%E6%94%BE%E4%BB%BB%20E%20%E5%8A%A8%22%7C%20FLOAT%5B%22%E5%9B%BA%E5%AE%9A%E6%B1%87%E7%8E%87%E7%A0%B4%E5%8A%9F%22%5D%0A%20%20CHOICE%20--%3E%7C%22%E8%B7%9F%E9%9A%8F%20i*%22%7C%20LOSE%5B%22%E8%B4%A7%E5%B8%81%E6%94%BF%E7%AD%96%E4%B8%8D%E7%8B%AC%E7%AB%8B%22%5D%0A%20%20CHOICE%20--%3E%7C%22%E5%85%B3%E9%97%B8%22%7C%20CTRL%5B%22%E8%B5%84%E6%9C%AC%E7%AE%A1%E5%88%B6%3A%20%E5%BC%80%E6%94%BE%E7%A0%B4%E5%8A%9F%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=i('<p>银行与中介并不因为选了某一角而消失：存款仍是支付手段，初级贷款仍难直接持有。后课从 Gurley–Shaw 接过转换功能。汇率制度只改变中介面对的宏观名义锚与资本流。</p><p><span class="marginnote">中间制度（管理浮动、软钉、有限管制）是边上的点，不是第四个可同时满足的顶点。Rey 的全球金融周期称浮动也买不到完全独立——边界修正，不是否定会计式套利。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>三角不是福利排序。浮动的 \\(q\\) 波动、管制的寻租、钉住的输入通胀，都要另评。货币联盟是把「独立货币」上交，相当于大范围的钉住。本栏不把三角写成外汇交易员的头寸；接到<a href="/quant/lob-structure">限价簿</a>之前，这里只停在宏观制度。CIP 三边套利属于报价层，见 <code>/quant/irp</code>；制度三角约束的是政策目标集合。</p><p><span class="marginnote">常见误区：把制度三角与量化里的 CIP 三边套利混为一谈。前者约束的是央行能同时承诺哪些宏观目标，后者是交易平台上「三个报价必须一致否则白捡钱」的无风险条件——一个谈政策空间，一个谈报价纪律，层级不同，名字里的「三」也互不相干。</span></p><p>后课默认：开放宏观的政策空间按三选二来读。之后进入货币银行：中介为何要把初级债权改写成存款。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>独立货币、固定汇率、资本自由流动不能同时成立。</li><li>每一角对应蒙代尔–弗莱明里已经见过的内生变量。</li><li>长期中性与 PPP 决定名义锚在本国还是外国。</li><li>宣布三角全占是不可信承诺。</li><li>市场层 CIP 与制度层三角不要混成一句。</li><li>出处：Mundell 的开放政策分派；Fleming 固定与浮动下的稳定政策。</li></ul>',8))])}const D=A(p,[["render",d]]);export{P as __pageData,D as default};
